int main() {
  const std::multiset<int> left{3, -2, 3};
  const std::multiset<int> right{-2, 3, 4};
  const std::multiset<int> equal{3, 3, -2};
  return left == equal && left != right && left < right &&
         right >= left && !(right <= left) ? 0 : 1;
